window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"1-ewayJ7Fs0","speaker":"King Mswati III","role":"Head of State","country":"Eswatini","region":"Africa","url":"https://www.youtube.com/watch?v=1-ewayJ7Fs0","date":"20260923","title":"🇸🇿 Eswatini - Head of State Addresses United Nations General Assembly 81st Session | #UNGA","seconds":1481,"words":2140,"counts":{"claims":38,"promises":3,"attacks":0},"topics":[{"topic":"UN cooperation","share":0.0996,"seconds":148},{"topic":"Eswatini agriculture","share":0.0918,"seconds":136},{"topic":"UN Security Council","share":0.0849,"seconds":126},{"topic":"Eswatini health","share":0.0609,"seconds":90},{"topic":"Eswatini economy","share":0.0541,"seconds":80},{"topic":"Taiwan status","share":0.0509,"seconds":75},{"topic":"UN peacekeeping","share":0.0503,"seconds":75},{"topic":"African health","share":0.0503,"seconds":75},{"topic":"African peace","share":0.0503,"seconds":74},{"topic":"AI governance","share":0.0492,"seconds":73},{"topic":"Conflict economics","share":0.0467,"seconds":69},{"topic":"UN role","share":0.0466,"seconds":69},{"topic":"Sustainable development","share":0.0463,"seconds":69},{"topic":"Regional integration","share":0.0461,"seconds":68},{"topic":"Climate change","share":0.0443,"seconds":66},{"topic":"UN General Assembly","share":0.044,"seconds":65},{"topic":"Global economy","share":0.0426,"seconds":63},{"topic":"International relations","share":0.041,"seconds":61}],"timeline":[[2,64,null],[65,130,"UN General Assembly"],[131,200,"UN role"],[202,263,"International relations"],[265,329,"UN Security Council"],[330,391,"UN Security Council"],[393,462,"Conflict economics"],[464,538,"African peace"],[539,614,"UN peacekeeping"],[616,684,"Regional integration"],[687,756,"Sustainable development"],[758,821,"Global economy"],[823,896,"AI governance"],[898,978,"Eswatini economy"],[980,1070,"Eswatini health"],[1071,1146,"African health"],[1147,1213,"Climate change"],[1214,1279,"Eswatini agriculture"],[1281,1352,"Eswatini agriculture"],[1358,1433,"Taiwan status"],[1434,1513,"UN cooperation"],[1514,1583,"UN cooperation"]],"stances":{"UN General Assembly":"King Mswati III expresses humility and privilege in addressing the session while highlighting its theme of restoring trust.","UN role":"King Mswati III states that the United Nations was established to prevent war tragedies and remains a vital platform for dialogue and action, though he notes current challenges like conflict and climate disasters.","International relations":"King Mswati III argues that the international community must renew its commitment to global cooperation and transform the UN into an organization that actively solves problems rather than just discussing them.","UN Security Council":"King Mswati III states that Africa lacks a permanent seat on the UN Security Council despite the 2005 Isuluini consensus and calls for honoring existing promises to restore trust.","Conflict economics":"King Mswati III argues that conflicts divert resources from development to military spending and increase living costs, while asserting that peace is essential for development.","African peace":"King Mswati III advocates for strengthening African-led peace processes and supporting regional organizations to prevent conflict and mediate disputes.","UN peacekeeping":"King Mswati III calls for UN oversight to ensure compliance with peace agreements and highlights Eswatini's role in promoting regional stability.","Regional integration":"King Mswati III states that achieving SADC's vision requires a peaceful, competitive, and industrialized region while expressing concern over government changes that violate UN and AU principles.","Sustainable development":"King Mswati III asserts that sustainable development must remain central to global efforts and highlights the challenges developing countries face in achieving the SDGs.","Global economy":"King Mswati III argues that economic development requires shifting from raw material exports to value addition and local industrialization, while emphasizing the need for governance of digital innovation.","AI governance":"King Mswati III states that emerging technologies like AI are advancing faster than current governance capacity and highlights the risks of a digital divide, while affirming Eswatini's commitment to building an inclusive economy.","Eswatini economy":"King Mswati III states that Eswatini is investing in various sectors and appeals to the UN for support to enhance African capacity in value addition and trade.","Eswatini health":"King Mswati III states that Eswatini's economic progress is vulnerable to global health emergencies and emphasizes the need for a vigilant health system.","African health":"King Mswati III calls for international support to build local pharmaceutical manufacturing in Africa and advocates for regional bloc purchasing to reduce costs.","Climate change":"King Mswati III argues that climate action must be accompanied by climate justice and calls for stronger international cooperation to support developing countries.","Eswatini agriculture":"King Mswati III states that Eswatini is intensifying investment in agriculture and providing subsidies to ensure food security for all families.","Taiwan status":"King Mswati III advocates for the United Nations to facilitate Taiwan's substantive participation in its meetings and activities.","UN cooperation":"King Mswati III argues that the United Nations should prioritize areas of possible cooperation over perfect consensus and reaffirm its role as a platform where all nations have a voice."},"claims":[{"t":80,"quote":"it is with the profound humility and great privilege that I address this 81st session of the United Nations General","topic":"UN General Assembly","kind":"fact"},{"t":92,"quote":"We congratulate the president of the 81st session on assuming this office and embracing a theme that is both timely and Restoring trust, managing a united Nations that delivers for all.","topic":"UN General Assembly","kind":"fact"},{"t":144,"quote":"The United Nations was born in 1945 from humanity's determination that the tragedies of war should never again define our common destiny.","topic":"UN role","kind":"fact"},{"t":160,"quote":"Eight decades later, the world continues to look to this organization as a century where nations can assembly, where differences can be resolved through dialogue and where hope can be transformed into tangible action.","topic":"UN role","kind":"fact"},{"t":228,"quote":"The true test of international cooperation is whether a child in a conflict affected community can live without fear. A young person can find decent employment. A family can afford food and a developing nation can access the finance required to build its Trust among nations has eroded on multiple fronts. Multilateral commitments have too often gone unmet.","topic":"International relations","kind":"fact"},{"t":265,"quote":"Financing pledges have not yet been fulfilled and developing countries face trillions of dollars in annual investment gaps to achieve the sustainable development goals.","topic":"UN Security Council","kind":"fact"},{"t":282,"quote":"billions of people reside in countries where governments are forced to spend more on debt servicing than on health care or education.","topic":"UN Security Council","kind":"fact"},{"t":317,"quote":"Since the Isuluini consensus was adopted in 2005, sadly Africa still has no permanent seat on the UN Security Council.","topic":"UN Security Council","kind":"fact"},{"t":335,"quote":"the continent the continent remains a global strategic partner in the world stage","topic":"UN Security Council","kind":"fact"},{"t":378,"quote":"multiple wars and armed conflicts continue to claim lives, destroy infrastructure, and displace communities across various regions of the world","topic":"UN Security Council","kind":"fact"},{"t":401,"quote":"They divert resources that are urgently needed for development into military expenditure.","topic":"Conflict economics","kind":"fact"},{"t":410,"quote":"They also drive up energy and transportation cost, disrupt global supply chains, and ex excessate the rising cost of living felt by people","topic":"Conflict economics","kind":"fact"},{"t":472,"quote":"While war may create temporal victories on the battlefield, only through dialogue can sustainable peace be","topic":"African peace","kind":"fact"},{"t":487,"quote":"The United Nations must remain the place where the door to dialogue never closes.","topic":"African peace","kind":"fact"},{"t":573,"quote":"During the 46th Sardak Summit, Esatini assumed the chairmanship of the Sardak organ on politics, defense and security cooperation troa whose whose mandate is to promote peace and stability in the southern African","topic":"UN peacekeeping","kind":"fact"},{"t":617,"quote":"for Saddak to attain its vision 2050, we have to create a peaceful, competitive and industrialized region that guarantees sustainable well-being and freedom for all our citizens.","topic":"Regional integration","kind":"fact"},{"t":639,"quote":"The African Union's agenda 2063 and its aspiration to silence the guns reflect our continent's resolve to end conflict and create the s and to create the stable conditions required for sustainable growth.","topic":"Regional integration","kind":"fact"},{"t":728,"quote":"The promise of the sustainable development goals SDGs is a pledge that no person and no country should be left behind.","topic":"Sustainable development","kind":"fact"},{"t":741,"quote":"Yet developing countries continue to face significant challenges including limited access to finance, technology, infrastructure, health care, education and productive investment.","topic":"Sustainable development","kind":"fact"},{"t":766,"quote":"We need to shift from the exportation of unprocessed raw materials to value addition, local industrialization, and the creation of decent jobs within our own borders.","topic":"Global economy","kind":"fact"},{"t":791,"quote":"The transformation brought about by digitalization and artificial intelligence presents enormous opportunities for humanity.","topic":"Global economy","kind":"fact"},{"t":823,"quote":"Emerging technologies, particularly artificial intelligence, are advancing faster than uh our current capacity to govern them while retaining human agency and control.","topic":"AI governance","kind":"fact"},{"t":860,"quote":"In the Kingdom of Swatini remains committed to building a more resilient, and inclusive economy.","topic":"AI governance","kind":"self_credit"},{"t":899,"quote":"we continue to invest strategically in human capital, health care, education, agriculture, tourism, industrialization and digital development, mining while positioning esatini effectively within regional and global value chains.","topic":"Eswatini economy","kind":"fact"},{"t":954,"quote":"the African continental free trade area provides a vital platform for African nations to move beyond raw material exports towards greater value addition, industrial processing and intra African trade so as to fulfill our vision.","topic":"Eswatini economy","kind":"fact"},{"t":1034,"quote":"The coid9 pandemic taught humanity a vital lesson. No country can protect itself from a global health emergency","topic":"Eswatini health","kind":"fact"},{"t":1051,"quote":"recent resurgences of impulse, recurring Ebola outbreaks, and other emerging infectious diseases remind us that our health system must remain vigilant","topic":"Eswatini health","kind":"fact"},{"t":1094,"quote":"In a recent meeting of the East, Central and Southern African Health Community Conference held in Eswatini, the country's resolve to act as a singular block when purchasing essential drugs and medical supplies.","topic":"African health","kind":"fact"},{"t":1147,"quote":"Developing countries contribute minimal to global emissions yet bear the brunt the brunt of uh droughts, floods, shifting weather patterns and climate induced shocks.","topic":"Climate change","kind":"fact"},{"t":1202,"quote":"In our region, we are currently confronted by what has been predicted as one of the most severe El Nino weather patterns on record.","topic":"Climate change","kind":"fact"},{"t":1235,"quote":"Our national objective is to ensure that every family has access to sufficient, safe and nutritious food.","topic":"Eswatini agriculture","kind":"fact"},{"t":1270,"quote":"We continue to provide subsidies for farming inputs and implements to support sub substances farmers.","topic":"Eswatini agriculture","kind":"fact"},{"t":1282,"quote":"we have embarked on a major dam construction projects for irrigation which are set to transform our agricultural landscape particularly in the law field.","topic":"Eswatini agriculture","kind":"fact"},{"t":1305,"quote":"The partnership between the United Nations and the Kingdom of Esatini has been instrumental in advancing our national development aspirations and implementing the and implementing the This collaboration spans critical sectors including health, tourism, education, agriculture, and renewable energy.","topic":"Eswatini agriculture","kind":"fact"},{"t":1368,"quote":"Taiwan plays a vital role in global supply chains. It has much to contribute to the international community and can play a highly meaningful role in building a sustainable future for humanity.","topic":"Taiwan status","kind":"fact"},{"t":1434,"quote":"The world does not require perfect consensus on every issue. It needs the courage to identify areas where cooperation is possible and will and and the will to act upon them.","topic":"UN cooperation","kind":"fact"},{"t":1452,"quote":"Let us restore faith in diplomacy and dialogue. Let us reestablish trust in international cooperation and above all reaffirm our belief that humanity's shared challenges can be addressed when nations chooses cooperation over division.","topic":"UN cooperation","kind":"fact"},{"t":1522,"quote":"The Kingdom of Esatini stands ready to work with all member states. the United Nations system, regional organizations, and international partners to advance peace, dialogue, sustainable development and human dignity for all.","topic":"UN cooperation","kind":"fact"}],"promises":[{"t":601,"quote":"Through this uh responsibility, we will work closely with all member states to strengthen preventative enhance dialogue and mediation.","topic":"UN peacekeeping","kind":"promise"},{"t":1253,"quote":"To achieve this, we are intensifying investment in agriculture, modern farming technologies, research, infrastructure, and the and the empowerment of our smallh holder","topic":"Eswatini agriculture","kind":"promise"},{"t":1336,"quote":"remain committed to ensuring a strong and enduring United Nation United Nations presence in our country, including the establishment of a permanent UN home in Eswati.","topic":"Eswatini agriculture","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"The assembly will hear an address by his majesty King Musati head of state of the Kingdom of Esatini. I request protocol to escort his majesty and invite him to address the assembly. Get your Mr."},{"t":65,"topic":"UN General Assembly","text":"President of the General Assembly, your Majesties, Excellencies, Heads of State and Mr. Secretary General, ladies and gentlemen, it is with the profound humility and great privilege that I address this 81st session of the United Nations General We congratulate the president of the 81st session on assuming this office and embracing a theme that is both timely and Restoring trust, managing a united Nations that delivers for all. This theme speaks directly to two of the most pressing questions facing the international community today. First, firstly, can we restore trust in our collective systems?"},{"t":131,"topic":"UN role","text":"And secondly, can we manage the great transformations of our time in a way that leaves no country, no person behind? The United Nations was born in 1945 from humanity's determination that the tragedies of war should never again define our common destiny. Eight decades later, the world continues to look to this organization as a century where nations can assembly, where differences can be resolved through dialogue and where hope can be transformed into tangible action. Yet at a time when conflicts persist, inequalities deepen, climate related disasters intensify, and countless communities continue to struggle against poverty and insecurity."},{"t":202,"topic":"International relations","text":"The international community must renew its commitment to global cooperation to ordinary people across the globe. This assembly must not be perceived merely as a forum where the world discusses its problems but as an organization that actively solves them. The true test of international cooperation is whether a child in a conflict affected community can live without fear. A young person can find decent employment. A family can afford food and a developing nation can access the finance required to build its Trust among nations has eroded on multiple fronts. Multilateral commitments have too often gone unmet."},{"t":265,"topic":"UN Security Council","text":"Financing pledges have not yet been fulfilled and developing countries face trillions of dollars in annual investment gaps to achieve the sustainable development goals. Furthermore, billions of people reside in countries where governments are forced to spend more on debt servicing than on health care or education. Restoring trust cannot be achieved through declarations alone. It requires that uh promises already made be honored and that our institutions demonstrate the capacity and will have to respond to changing global realities. Since the Isuluini consensus was adopted in 2005, sadly Africa still has no permanent seat on the UN Security Council."},{"t":330,"topic":"UN Security Council","text":"And yet and yet the continent the continent remains a global strategic partner in the world stage. The question is, how many more years should African leaders travel to New York and stand before this assembly to call for a fair in the UN Security Council. Mr. President, we are being deprived of the opportunity to contribute to global security issues. We meet at a time when multiple wars and armed conflicts continue to claim lives, destroy infrastructure, and displace communities across various regions of the world."},{"t":393,"topic":"Conflict economics","text":"Beyond the immediate human tragedy, these conflicts exert a heavy economic toll. They divert resources that are urgently needed for development into military expenditure. They also drive up energy and transportation cost, disrupt global supply chains, and ex excessate the rising cost of living felt by people Peace remains the indispensable foundation upon which all development is Where there is war, development is Where there is instability, investment Where there is fear, human potential is The Kingdom of Esatini remains deeply concerned by the continued conflict and humanitarian crisis affecting various parts of our world."},{"t":464,"topic":"African peace","text":"We call for the continued pursuit of diplomatic and political solutions to these conflicts. While war may create temporal victories on the battlefield, only through dialogue can sustainable peace be The United Nations must remain the place where the door to dialogue never closes. On the African continent, continued validates the urgent need to strengthen African-led peace processes. There's also a need to support the capacity of African regional organizations to prevent conflict, mediate disputes, and build sustainable The Kingdom of Swadini believes firmly peace in Europe, Middle East and Africa must be echoed in preventing diplomacy fully supported by the United Nations."},{"t":539,"topic":"UN peacekeeping","text":"We call upon the UN to ensure that countries respect peace agreements that have been signed to avoid drawing back on the gains already made, thus causing more destruction to infrastructure and innocent lives. The UN should provide oversight to ensure follow-ups and monitor compliance on these agreements to last forever. During the 46th Sardak Summit, Esatini assumed the chairmanship of the Sardak organ on politics, defense and security cooperation troa whose whose mandate is to promote peace and stability in the southern African Through this uh responsibility, we will work closely with all member states to strengthen preventative enhance dialogue and mediation."},{"t":616,"topic":"Regional integration","text":"We believe that uh for Saddak to attain its vision 2050, we have to create a peaceful, competitive and industrialized region that guarantees sustainable well-being and freedom for all our citizens. The African Union's agenda 2063 and its aspiration to silence the guns reflect our continent's resolve to end conflict and create the s and to create the stable conditions required for sustainable growth. However, we are concerned by the continued incidents of changes of government which run counter to the values and principles enshrined in the charters of the United Nations, the African Union and the original economic blocks."},{"t":687,"topic":"Sustainable development","text":"Respect for constitutional order and the rule of law is fundamental to stability. We urge the international community to speak with one voice against its The United Nations should fully support decisions taken by regional bodies to condemn such acts which cause immense sufferings and uncertainty for millions of people. Sustainable development must remain at the center of our collective endeavor. The promise of the sustainable development goals SDGs is a pledge that no person and no country should be left behind. Yet developing countries continue to face significant challenges including limited access to finance, technology, infrastructure, health care, education and productive investment."},{"t":758,"topic":"Global economy","text":"Economic development must increasingly mean the structural transformation of our economies. We need to shift from the exportation of unprocessed raw materials to value addition, local industrialization, and the creation of decent jobs within our own borders. This economic growth objective is now inseparable from the emerging The transformation brought about by digitalization and artificial intelligence presents enormous opportunities for humanity. It is it has the power to expand access to education, health care, financial services and economic opportunities. However, innovation must be governed by and accountability."},{"t":823,"topic":"AI governance","text":"Emerging technologies, particularly artificial intelligence, are advancing faster than uh our current capacity to govern them while retaining human agency and control. This raises critical questions regarding safety, environmental impact and the risk of a widening digital divide between those who can shape these technologies and those who are excluded from their benefits. In the Kingdom of Swatini remains committed to building a more resilient, and inclusive economy. Our vision is to create an economy that generates decent employment, attracts sustained investment, expands opportunities for our youth, women and marginalized groups amongst others to strengthen their livelihoods."},{"t":898,"topic":"Eswatini economy","text":"To this end, we continue to invest strategically in human capital, health care, education, agriculture, tourism, industrialization and digital development, mining while positioning esatini effectively within regional and global value chains. We appeal to the UN for support towards enhancing the capacity of African countries in developing value addition on their natural resources as well as creating a trading hub for precious and earth minerals and other commodities for the continent. In this regard, the African continental free trade area provides a vital platform for African nations to move beyond raw material exports towards greater value addition, industrial processing and intra African trade so as to fulfill our vision."},{"t":980,"topic":"Eswatini health","text":"No country can achieve sustainable development while large segments of its population remain on the margins of the economic mainstream. Our citizens must not be viewed merely as beneficiaries of employment. They must be full participants as key pillars of our sustainable growth. We have uh created an inclusive environment for all our people irrespective of their gender or religion at the apex of our economic growth Economic and social progress however remain vulnerable to global health The coid9 pandemic taught humanity a vital lesson. No country can protect itself from a global health emergency Yet even as we recover from that crisis, recent resurgences of impulse, recurring Ebola outbreaks, and other emerging infectious diseases remind us that our health system must remain vigilant and We must decisively address"},{"t":1071,"topic":"African health","text":"persistent inequalities in access to vaccines, medicines, and medical technologies. Critical, the international community must support African countries in developing robust local and regional capacities to manufacture essential pharmaceuticals and health products. In a recent meeting of the East, Central and Southern African Health Community Conference held in Eswatini, the country's resolve to act as a singular block when purchasing essential drugs and medical supplies. This will help reduce cost and ensure supply chain stability. We appeal to the UN through the World Health Organization to support this Parallel to health, security is the fundamental crisis of climate change which is another defining challenge of our generation."},{"t":1147,"topic":"Climate change","text":"Developing countries contribute minimal to global emissions yet bear the brunt the brunt of uh droughts, floods, shifting weather patterns and climate induced shocks. Therefore, climate action must be accompanent by climate justice. We call for stronger international cooperation in climate adaptation, resilience, technology transfer, capacity building, and access to predictable, affordable climate finance. We must protect our environment, not only for our present generation, but for those yet unborn. In our region, we are currently confronted by what has been predicted as one of the most severe El Nino weather patterns on record."},{"t":1214,"topic":"Eswatini agriculture","text":"Addressing this requires us to draw deeply upon strained national resources to protect our people and preserve their livelihoods. Directly linked to climate resilience is our commitment to food security. Our national objective is to ensure that every family has access to sufficient, safe and nutritious food. This is a matter of basic human dignity and sustainable development. To achieve this, we are intensifying investment in agriculture, modern farming technologies, research, infrastructure, and the and the empowerment of our smallh holder We continue to provide subsidies for farming inputs and implements to support sub substances farmers."},{"t":1281,"topic":"Eswatini agriculture","text":"Furthermore, we have embarked on a major dam construction projects for irrigation which are set to transform our agricultural landscape particularly in the law field. National endeavors such as this are greatly enhanced by international The partnership between the United Nations and the Kingdom of Esatini has been instrumental in advancing our national development aspirations and implementing the and implementing the This collaboration spans critical sectors including health, tourism, education, agriculture, and renewable energy. We deeply value this uh partnership and remain committed to ensuring a strong and enduring United Nation United Nations presence in our country, including the establishment of a permanent UN home in Eswati."},{"t":1358,"topic":"Taiwan status","text":"Just as partnerships at home are vital, so is inclusive participation on the international stage. Taiwan plays a vital role in global supply chains. It has much to contribute to the international community and can play a highly meaningful role in building a sustainable future for humanity. The United Nations should seek appropriate ways to facilitate Taiwan's sub substantive participation in UN meetings and activities, enabling it to share its expertise and actively engage with the international partners. Mr. President, as we convene at this pital pivotal moment in the life of the United let us remember that our differences need not prevent us from finding common ground."},{"t":1434,"topic":"UN cooperation","text":"The world does not require perfect consensus on every issue. It needs the courage to identify areas where cooperation is possible and will and and the will to act upon them. Let us restore faith in diplomacy and dialogue. Let us reestablish trust in international cooperation and above all reaffirm our belief that humanity's shared challenges can be addressed when nations chooses cooperation over division. The United Nations must remain a house where every nation, large or small, has a voice and where the sovereignty and dignity of all member states are fully As world leaders, we come here every year to promote dignity, peace, justice, humanity, and cooperation in order to create a better world."},{"t":1514,"topic":"UN cooperation","text":"And we should never give up to fight for it. The Kingdom of Esatini stands ready to work with all member states. the United Nations system, regional organizations, and international partners to advance peace, dialogue, sustainable development and human dignity for all. We take this opportunity to extend our appreciation to all UN agencies and the support structures for their diligent work in ensuring the success of this g of of this gathering and execution of their various duties. I thank you. May almighty God bless us all. On behalf of the assembly, I wish to thank the head of state of the kingdom of Esatini."}],"compare":[{"topic":"UN & its reform","share":0.3255,"mean":0.2041,"rank":37,"others":170},{"topic":"Africa","share":0.1006,"mean":0.0231,"rank":19,"others":36},{"topic":"Global Economy","share":0.0893,"mean":0.0142,"rank":10,"others":31},{"topic":"Taiwan","share":0.0509,"mean":0.0026,"rank":6,"others":7},{"topic":"Artificial Intelligence","share":0.0492,"mean":0.0505,"rank":77,"others":83},{"topic":"Sustainable Development","share":0.0463,"mean":0.0123,"rank":26,"others":28},{"topic":"Regional Security","share":0.0461,"mean":0.0044,"rank":11,"others":12},{"topic":"Climate Change","share":0.0443,"mean":0.0428,"rank":75,"others":77}]};
